# Expected values generated by test/einops/gen_expected.py (einops 0.8.2).
import torch
import einops
from einops.layers.torch import Rearrange, Reduce

x = torch.arange(24, dtype=torch.float64).reshape([2, 3, 4])
y = torch.arange(120, dtype=torch.float64).reshape([2, 3, 4, 5])

def check(t: torch.Tensor, shape: List[int], vals: List[float]) -> bool:
    return list(t.shape) == shape and t.contiguous().reshape([-1]).tolist() == vals

